CREATE OR REPLACE FUNCTION public.community_summary() RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT jsonb_build_object('plays',coalesce((SELECT jsonb_agg(t) FROM (SELECT game_name,count(DISTINCT user_id) AS plays FROM play_events GROUP BY game_name ORDER BY count(DISTINCT user_id) DESC,game_name LIMIT 20)t),'[]'::jsonb),'ratings',coalesce((SELECT jsonb_agg(t) FROM (SELECT game_name,avg(rating) AS average,count(*) AS votes FROM game_ratings GROUP BY game_name ORDER BY (sum(rating)+15.0)/(count(*)+5) DESC,game_name LIMIT 100)t),'[]'::jsonb),'players',coalesce((SELECT jsonb_agg(t) FROM (SELECT md5(p.id::text) AS id,p.display_name,p.avatar_url,coalesce((SELECT sum(points) FROM xp_events x WHERE x.user_id=p.id),0) AS plays FROM profiles p WHERE p.leaderboard_enabled ORDER BY plays DESC,p.display_name,p.id LIMIT 20)t),'[]'::jsonb),'requests',coalesce((SELECT jsonb_agg(t) FROM (SELECT r.id,CASE WHEN r.user_id=auth.uid() THEN r.user_id ELSE NULL END user_id,r.title,r.description,r.status,r.created_at,p.display_name,(SELECT count(*) FROM request_votes v WHERE v.request_id=r.id) AS votes FROM game_requests r JOIN profiles p ON p.id=r.user_id ORDER BY votes DESC,r.created_at DESC,r.id LIMIT 100)t),'[]'::jsonb)); $$;
REVOKE SELECT ON public.game_requests FROM anon;
DROP POLICY public_requests ON public.game_requests;
CREATE POLICY own_requests_read ON public.game_requests FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.admin_is_unlocked());
CREATE OR REPLACE FUNCTION public.validate_request_insert_status() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NOT admin_is_unlocked() THEN NEW.status='open'; END IF; RETURN NEW; END $$;
CREATE TRIGGER request_insert_status BEFORE INSERT ON public.game_requests FOR EACH ROW EXECUTE FUNCTION public.validate_request_insert_status();